import React, { useEffect, useState } from "react";
import {
  getDashboard,
  getNotices,
  addNotice,
  deleteNotice,
  addStudy,
  uploadPDF
} from "../../services/api";

function AdminDashboard() {
  const token = localStorage.getItem("token");

  const [stats, setStats] = useState({});
  const [notices, setNotices] = useState([]);

  const [noticeForm, setNoticeForm] = useState({
    title: "",
    content: ""
  });

  const [studyForm, setStudyForm] = useState({
    title: "",
    content: "",
    subject: ""
  });

  const [file, setFile] = useState(null);

  // LOAD DATA
  useEffect(() => {
    loadDashboard();
    loadNotices();
  }, []);

  const loadDashboard = async () => {
    const res = await getDashboard(token);
    setStats(res.data);
  };

  const loadNotices = async () => {
    const res = await getNotices();
    setNotices(res.data);
  };

  // NOTICE ADD
  const handleAddNotice = async () => {
    await addNotice(noticeForm, token);
    loadNotices();
  };

  // NOTICE DELETE
  const handleDeleteNotice = async (id) => {
    await deleteNotice(id, token);
    loadNotices();
  };

  // STUDY ADD
  const handleAddStudy = async () => {
    await addStudy(studyForm, token);
    alert("Study added");
  };

  // PDF UPLOAD
  const handleUpload = async () => {
    await uploadPDF(file, token);
    alert("PDF Uploaded 🚀");
  };

  return (
    <div className="dashboard">

      <h2>Admin Dashboard</h2>

      {/* STATS */}
      <div className="grid">
        <div className="card">Users: {stats.total_users}</div>
        <div className="card">Notices: {stats.total_notices}</div>
        <div className="card">Study: {stats.total_study}</div>
      </div>

      {/* NOTICE SECTION */}
      <div className="card" style={{ marginTop: 20 }}>
        <h3>Notices</h3>

        <input placeholder="Title"
          onChange={(e) =>
            setNoticeForm({ ...noticeForm, title: e.target.value })
          }
        />

        <input placeholder="Content"
          onChange={(e) =>
            setNoticeForm({ ...noticeForm, content: e.target.value })
          }
        />

        <button className="btn-primary" onClick={handleAddNotice}>
          Add Notice
        </button>

        {notices.map((n) => (
          <div key={n._id} className="card">
            <h4>{n.title}</h4>
            <p>{n.content}</p>

            <button
              className="btn-primary"
              onClick={() => handleDeleteNotice(n._id)}
            >
              Delete
            </button>
          </div>
        ))}
      </div>

      {/* STUDY SECTION */}
      <div className="card" style={{ marginTop: 20 }}>
        <h3>Study Material</h3>

        <input placeholder="Title"
          onChange={(e) =>
            setStudyForm({ ...studyForm, title: e.target.value })
          }
        />

        <input placeholder="Subject"
          onChange={(e) =>
            setStudyForm({ ...studyForm, subject: e.target.value })
          }
        />

        <textarea placeholder="Content"
          onChange={(e) =>
            setStudyForm({ ...studyForm, content: e.target.value })
          }
        />

        <button className="btn-primary" onClick={handleAddStudy}>
          Add Study
        </button>
      </div>

      {/* PDF UPLOAD */}
      <div className="card" style={{ marginTop: 20 }}>
        <h3>Upload PDF</h3>

        <input type="file"
          onChange={(e) => setFile(e.target.files[0])}
        />

        <button className="btn-primary" onClick={handleUpload}>
          Upload PDF
        </button>
      </div>

    </div>
  );
}

export default AdminDashboard;
